export function normalizeDoi(value:unknown):string|null {if(typeof value!=='string')return null;const doi=value.trim().replace(/^(?:https?:\/\/(?:dx\.)?doi\.org\/|doi:\s*)/i,'').toLowerCase();return /^10\.\d{4,9}\/[^\s\x00-\x20]+$/.test(doi)?doi:null;}
