    ensure(q.template==='positive-benefit-v1','METHOD_WITNESS_REQUIRED','paired-rmse-delta-v1必须从本次实际归档的预测见证计算，不能只接收自命名metrics');
    const names=[q.gain.metric,q.interval.lowerMetric,q.interval.upperMetric],values=names.map(name=>metrics[name]);ensure(values.every(v=>typeof v==='number'&&Number.isFinite(v)),'METHOD_METRICS_INVALID','方法判定需要全部有限数值指标');
    const [gain,lower,upper]=values;ensure(lower<=upper,'METHOD_METRICS_INVALID','方法区间上下界颠倒');
