export function methodRequiredPaths(contract:FrozenMethodContract) {const q=contract.specification.quantitative;return [...new Set([...methodHostPaths(contract),...(q.type==='comparison'?q.decisionOutputs?.map(d=>d.artifactPath)??[]:[]),...(q.type==='comparison'&&q.template!=='positive-benefit-v1'?[q.witness.artifactPath]:[]),...(isPlan(q)?[q.provenanceArtifact]:[])])];}
