export function methodAttachments(contract:FrozenMethodContract,protocolText:string,result:unknown,artifacts?:Archived[]) {const resultFiles=new Map<string,Buffer>([['methods-protocol.md',Buffer.from(protocolText)],['methods-ledger.json',Buffer.from(JSON.stringify(contract.literatureLedger,null,2))],['methods-boundaries.json',Buffer.from(JSON.stringify(contract.boundaryExamples,null,2))],['methods-results.json',Buffer.from(JSON.stringify(result,null,2))]]);const q=closedPaired(contract);if(q){const r=result as {facts:BearingFacts};ensure(artifacts,'METHOD_OUTPUT_PROFILE_INVALID','host导出需要原始见证');const witness=artifacts.find(a=>a.title===q.witness.artifactPath)!;for(const [name,bytes]of bearingExports(r.facts,atPointer(witnessJson(witness.bytes),q.witness.recordsPointer) as Array<Record<string,unknown>>,q))resultFiles.set(name,bytes);}return resultFiles;}
export function assertMethodArchive(contract:FrozenMethodContract,protocolText:string,metric:Archived,metrics:Record<string,number>,binding:{sourceDigest:string;subjectId:string},artifacts:Archived[],fixture?:SyntheticFixtureContext,execution?:BearingExecution) {
    const expected=methodAttachments(contract,protocolText,methodResult(contract,metric,metrics,binding,artifacts,fixture,execution?{...execution,allowHost:true}:undefined),artifacts);
    for(const [name,bytes]of expected){const matches=artifacts.filter(a=>a.title===name);ensure(matches.length===1&&matches[0].digest===digest(bytes)&&matches[0].size===bytes.length&&matches[0].bytes.equals(bytes),'METHOD_RESULT_CORRUPTED',`宿主方法产物不符合原冻结规则或真实指标：${name}`);}
}
export function assertDevelopmentMethodArchive(store:Store,job:Row<SandboxJob>,contract:FrozenMethodContract|undefined,protocolText:string|undefined) {
    ensure(job.manifest.methodContractDigest===contract?.contractDigest,'METHOD_CONTRACT_CORRUPTED','方法结果丢失或改变了原清单契约标识');if(!contract)return;
    const archived=job.artifactIds.map(id=>{const a=store.get<Artifact>('artifact',id,job.projectId!),physical=store.paths.physical(a.path),bytes=readStableFile(dirname(physical),basename(physical),32*1024*1024);ensure(a.origin===`development:${job.id}`&&a.size===bytes.length&&a.digest===digest(bytes),'METHOD_RESULT_CORRUPTED','方法归档来源或字节已改变');return {...a,bytes};});
    if(closedPaired(contract)){const report=archived.find(a=>a.id===job.reportArtifactId);ensure(report,'METHOD_RESULT_CORRUPTED','缺少实际全产物归档回执');const receipt=JSON.parse(report.bytes.toString('utf8'));ensure(receipt.status===job.state&&receipt.integrity===job.integrity&&digest([...receipt.artifactIds].sort())===digest(job.artifactIds.filter(id=>id!==report.id).sort()),'METHOD_RESULT_CORRUPTED','实际归档全清单/状态与原回执不符，不能移除错材料后降级');}
    const artifacts=archived.filter(a=>a.title.startsWith('output/')).map(a=>({...a,title:a.title.slice(7)})),metrics=artifacts.filter(a=>a.title===job.manifest.metricArtifact);
    ensure(metrics.length===1,'METHOD_RESULT_CORRUPTED','缺少唯一的原始方法指标');
    const expected=methodSyntheticFixture(contract),fixture=expected?assertSyntheticManifest(store,job.projectId!,job.sessionId,expected,job.manifest.syntheticFixture,job.manifest.command,job.manifest.dataArtifacts):undefined;ensure(expected||!job.manifest.syntheticFixture,'SYNTHETIC_FIXTURE_BINDING_INVALID','旧计划不能自添synthetic验证身份');assertMethodArchive(contract,protocolText!,metrics[0],finiteMetrics(JSON.parse(metrics[0].bytes.toString('utf8'))),{sourceDigest:job.sourceDigest,subjectId:job.id},artifacts,fixture,{sourceFiles:job.manifest.inputSnapshot.files,logs:archived.filter(a=>!a.title.startsWith('output/')),successful:true});
}

export class MethodContractService {
    constructor(private app:ResearchApp) {}
    recordSkillRead(actor:Actor,selected:Row<Session>|undefined,value:unknown) {
        if(actor.type!=='agent'||!selected||actor.sessionId!==selected.id||actor.role!=='coordinator'||actor.taskId||selected.taskId||selected.teamId||actor.wakeupId)return;
        const s=this.app.store.get<Session>('session',selected.id,actor.projectId);ensure(s.state==='running'&&s.generation===actor.generation&&s.leaseUntil>Date.now(),'LEASE_EXPIRED','方法技能读取租约已失效');
        const output=value as {prerequisites?:unknown[]};for(const raw of [value,...output.prerequisites??[]]){const v=raw as {methodRequirements?:MethodRequirement[];id:string;resource:string;digest:string;bundleId:string};if(!v.methodRequirements?.length)continue;
            ensure(v.methodRequirements.every(r=>r==='literature-identity'||r==='quantitative-decision'||r==='structured-paired-protocol'||r==='closed-paired-evidence'),'METHOD_SPEC_INVALID','技能方法要求无效');const data={sessionId:s.id,anchorBriefId:s.researchBriefId??null,bundleId:v.bundleId,skillId:v.id,resource:v.resource,resourceDigest:v.digest,requirements:[...new Set(v.methodRequirements)]};const id=digest(data);if(!this.app.store.maybe('research-method-activation',id))this.app.store.create<MethodActivation>('research-method-activation',s.projectId!,data,id);
        }
    }
    requirements(s:Row<Session>,inherited:MethodRequirement[]=[]):MethodRequirement[] {return [...new Set([...inherited,...this.app.store.list<MethodActivation>('research-method-activation',s.projectId!).filter(a=>a.sessionId===s.id).flatMap(a=>a.requirements),...(s.researchBriefId&&this.app.store.get<import('./briefs.js').ResearchBrief>('research-brief',s.researchBriefId,s.projectId!).methodContract?.compilerVersion===CLOSED_COMPILER?['closed-paired-evidence' as const]:[]),...(hasSyntheticFixture(this.app.store,s.projectId!,s.id)?['structured-paired-protocol' as const]:[]),...(this.app.store.db.prepare("SELECT 1 FROM events WHERE project_id=? AND type='research.bearing_profile_selected' AND json_extract(payload,'$.sessionId')=? LIMIT 1").get(s.projectId!,s.id)?['closed-paired-evidence' as const]:[])])].sort();}
    supports(s:Row<Session>) {if(this.requirements(s).some(r=>r==='literature-identity'||r==='quantitative-decision'))return true;let bundle:string;try{bundle=sessionSkillBundle(this.app,s);}catch(error){if(asError(error).code==='SKILL_BINDING_UNKNOWN')return false;throw error;}return this.app.skills.bundleMethodRequirements(s.projectId!,s.role,bundle).some(r=>r==='literature-identity'||r==='quantitative-decision');}
    assertSelected(s:Row<Session>,contract:FrozenMethodContract|undefined,required=this.requirements(s)) {ensure(!required.includes('closed-paired-evidence')||contract?.compilerVersion===CLOSED_COMPILER,'METHOD_OUTPUT_PROFILE_REQUIRED','当前root已选择闭合paired证据流程，不能降级旧模板/删除profile');ensure(!required.includes('structured-paired-protocol')||contract?.compilerVersion===PLAN_COMPILER||contract?.compilerVersion===CLOSED_COMPILER,'METHOD_STRUCTURED_PLAN_REQUIRED','当前root已选择结构化paired多项式流程，不能降级旧模板/描述模式；先准备fixture并编译v3完整protocol');}
    preview(s:Row<Session>,specification:unknown,inputs:ResearchSourceInput[]|undefined) {
        const parsed=parseMethodSpecification(specification),allowed=this.app.sourceInputs.previewBytes(s,s.researchBriefId??null,inputs??[],parsed.literatureSources.map(s=>s.path)),q=parsed.quantitative;if(isPlan(q))assertSyntheticFixture(this.app.store,s.projectId!,q.developmentData.fixtureRef,s.id);const compiled=compileMethodContract(parsed,allowed);this.assertSelected(s,{...compiled,protocolPath:'protocol.md'});return compiled;
    }
    compile(actor:Actor,pid:string,sessionId:string,value:unknown) {
        this.app.researchBriefs.inspect(actor,pid,sessionId);const s=this.app.store.get<Session>('session',sessionId,pid),x=closed(value,['specification']),old=s.researchBriefId?this.app.researchBriefs.inspect(actor,pid,sessionId).brief:undefined;return this.preview(s,x.specification,old?.sourceInputs);
    }
    freeze(s:Row<Session>,value:unknown,inputs:ResearchSourceInput[],drafts:DraftFile[]|undefined):FrozenMethodContract {
        const x=closed(value,['protocolPath','specification']),protocolPath=relativePath(x.protocolPath),compiled=compileMethodContract(x.specification,sourceBytes(this.app.store,s.projectId!,inputs,parseMethodSpecification(x.specification))),file=drafts?.find(f=>f.path===protocolPath);
        ensure(file&&file.digest===compiled.protocolDigest,'METHOD_PROTOCOL_READ_REQUIRED','先research_method_compile，把完整protocol原样workspace_write并workspace_read回读，然后在draftFiles引用其draftReadId');
        const bytes=readStableFile(this.app.store.paths.physical(s.workspace),protocolPath,2*1024*1024);ensure(digest(bytes)===compiled.protocolDigest&&bytes.toString('utf8')===compiled.protocol,'METHOD_PROTOCOL_CHANGED','规范方法附件与确定性编译文本不符');
        const {protocol:_,...frozen}=compiled;return {...frozen,protocolPath};
    }
    validateReady(s:Row<Session>,value:unknown,inputs:ResearchSourceInput[]|undefined,drafts:DraftFile[]|undefined,inherited:FrozenMethodContract|undefined,required:MethodRequirement[],roles:unknown) {
        ensure(value!==undefined||inherited||!required.length||!drafts?.length,'METHOD_CONTRACT_REQUIRED','所选方法技能用于ready草稿时需要methodContract；先调用research_method_compile');
        if(value!==undefined){const x=closed(value,['protocolPath','specification']),compiled=this.preview(s,x.specification,inputs),path=relativePath(x.protocolPath),file=drafts?.find(f=>f.path===path),contract={...compiled,protocolPath:path};this.assertSelected(s,contract,required);ensure(file&&file.digest===compiled.protocolDigest,'METHOD_PROTOCOL_READ_REQUIRED','规范方法附件须为编译protocol原文并用当前draftReadId回读');validateProtocolRoles(contract,drafts,roles);}
        else {this.assertSelected(s,inherited,required);if(inherited){assertMethodSnapshot(inherited,drafts??[]);validateProtocolRoles(inherited,drafts,roles);}}
    }
}
